import { isEmpty } from 'lodash-es';
import React, { PropsWithChildren } from 'react';
import { isElement } from 'react-is';

import { ChartToolbar } from '../../core/slots/toolbar/ChartToolbar.js';
import { DownloadData } from '../../core/slots/toolbar/DownloadData.js';
import {
  ChartToolbarProps,
  ChartToolbarConfig,
} from '../../core/types/toolbar.js';
import { Grouping as DonutGrouping } from '../slots/DonutChartGrouping.js';
import { DonutChartInner } from '../slots/DonutChartInner.js';
import { Labels as DonutLabels } from '../slots/DonutChartLabels.js';
import { Legend as DonutLegend } from '../slots/DonutChartLegend.js';
import { Grouping as PieGrouping } from '../slots/PieChartGrouping.js';
import { Labels as PieLabels } from '../slots/PieChartLabels.js';
import { Legend as PieLegend } from '../slots/PieChartLegend.js';
import {
  PieChartSlots,
  PieChartLegendConfig,
  LabelsConfig,
  GroupConfig,
} from '../types/pie-chart.config.js';

/**
 * Generate chart config based on slots
 * @param children - CharInteraction children
 * @returns ChartInteraction slot config
 */
const iterateChartToolbarSlots = (
  children: React.ReactNode,
): ChartToolbarConfig => {
  let slots = {} as ChartToolbarConfig;

  React.Children.forEach(children, (childInteractions) => {
    if (isElement(childInteractions)) {
      switch (childInteractions.type) {
        case DownloadData:
          slots = { ...slots, downloadData: { enabled: true } };
          break;
      }
    }
  });

  return slots;
};

/**
 * Iterate over the slotted children to merge the configuration.
 * @param children - Slotted children to iterate
 * @returns Merged config as PieChartSlots
 */
export function iterateSlots(children: React.ReactNode): PieChartSlots {
  let slots: PieChartSlots = {
    labels: {},
    grouping: {},
    legend: {},
    toolbar: undefined,
    innerElement: undefined,
  };

  React.Children.map(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case PieLabels:
        case DonutLabels: {
          const labels = child.props as LabelsConfig;

          slots = { ...slots, labels };
          break;
        }

        case PieGrouping:
        case DonutGrouping: {
          const grouping = child.props as GroupConfig;

          slots = { ...slots, grouping };
          break;
        }

        case PieLegend:
        case DonutLegend: {
          const legend = child.props as PieChartLegendConfig;

          slots = { ...slots, legend };
          break;
        }

        case ChartToolbar: {
          const { children, ...toolbarProps } =
            child.props as PropsWithChildren<ChartToolbarProps>;

          const toolbarSlots = iterateChartToolbarSlots(children);

          const toolbar = isEmpty(toolbarSlots)
            ? undefined
            : { ...toolbarProps, ...toolbarSlots };
          slots = { ...slots, toolbar };
          break;
        }

        case DonutChartInner: {
          const inner = child.props.children;

          slots = { ...slots, innerElement: inner };
          break;
        }
      }
    }
  });

  return slots;
}
